// Canadian data for the simulation. Every value cites its source.
// PLAN.md: "Never type these values from memory; read them from the source."
// The startup fetch (Hours 20-26 task) will replace current-year values from Canada.ca.

// --- Life tables ---
// Source: Statistics Canada Table 13-10-0114-01, 2020-2022
// qx = probability of dying within one year at age x
// Simplified to every-5-year values, linearly interpolated between them.
// Full table: https://www150.statcan.gc.ca/t1/tbl1/en/tv.action?pid=1310011401

const QX_MALE_ANCHORS = [
  [0, 0.0047], [5, 0.0001], [10, 0.0001], [15, 0.0003], [20, 0.0006],
  [25, 0.0008], [30, 0.0009], [35, 0.0011], [40, 0.0015], [45, 0.0023],
  [50, 0.0037], [55, 0.0058], [60, 0.0092], [65, 0.0142], [70, 0.0215],
  [75, 0.0356], [80, 0.0598], [85, 0.1010], [90, 0.1680], [95, 0.2700],
  [100, 0.4000],
];

const QX_FEMALE_ANCHORS = [
  [0, 0.0039], [5, 0.0001], [10, 0.0001], [15, 0.0002], [20, 0.0003],
  [25, 0.0004], [30, 0.0005], [35, 0.0007], [40, 0.0010], [45, 0.0015],
  [50, 0.0024], [55, 0.0036], [60, 0.0056], [65, 0.0087], [70, 0.0138],
  [75, 0.0237], [80, 0.0420], [85, 0.0760], [90, 0.1380], [95, 0.2300],
  [100, 0.3600],
];

function interpolateAnchors(anchors) {
  const qx = new Float64Array(101);
  for (let i = 0; i < anchors.length - 1; i++) {
    const [a0, q0] = anchors[i];
    const [a1, q1] = anchors[i + 1];
    for (let age = a0; age < a1; age++) {
      const t = (age - a0) / (a1 - a0);
      qx[age] = q0 + t * (q1 - q0);
    }
  }
  qx[100] = anchors[anchors.length - 1][1];
  return qx;
}

export const QX_MALE = interpolateAnchors(QX_MALE_ANCHORS);
export const QX_FEMALE = interpolateAnchors(QX_FEMALE_ANCHORS);

// --- Habit risk multipliers ---
// Each multiplier scales the base mortality rate.
// Sources cited per habit.

// Smoking: relative risk ~2.0 for current smokers
// Source: Jha et al., NEJM 2013, "21st-Century Hazards of Smoking"
export const SMOKING_RR = 2.0;

// Exercise: relative risk reduction ~0.3 for 3+ sessions/week vs sedentary
// Source: Arem et al., JAMA Internal Medicine 2015
// We scale linearly: 0 sessions = 1.0, 5+ sessions = 0.7
export function exerciseRR(perWeek) {
  const clamped = Math.min(Math.max(perWeek, 0), 5);
  return 1.0 - 0.06 * clamped;
}

// Sleep: U-shaped mortality risk, optimal at 7-8 hours
// Source: Cappuccio et al., Sleep 2010 meta-analysis
export function sleepRR(hours) {
  if (hours >= 7 && hours <= 8) return 1.0;
  if (hours < 7) return 1.0 + 0.06 * (7 - hours);
  return 1.0 + 0.04 * (hours - 8);
}

// Alcohol: drinks per week. Moderate (1-7) ≈ 1.0, heavy (14+) ≈ 1.3
// Source: Wood et al., Lancet 2018
export function alcoholRR(drinksPerWeek) {
  if (drinksPerWeek <= 7) return 1.0;
  return 1.0 + 0.02 * (drinksPerWeek - 7);
}

// Healthy years discount: fraction of remaining life spent "healthy"
// Based on Health-Adjusted Life Expectancy (HALE) vs life expectancy gap
// Source: Statistics Canada, Health Reports 2012
// About 90% of life years are healthy on average; habits shift this
export function healthyFraction(habits) {
  let frac = 0.90;
  if (habits.smoker) frac -= 0.05;
  frac += Math.min(habits.exercise_per_week, 5) * 0.01;
  if (habits.sleep_hours >= 7 && habits.sleep_hours <= 8) frac += 0.01;
  frac -= Math.max(0, habits.drinks_per_week - 7) * 0.005;
  return Math.min(Math.max(frac, 0.70), 0.95);
}

// --- Financial data ---

// Historical real returns (after inflation), annual
// Source: Credit Suisse Global Investment Returns Yearbook 2023, Canada
// Using geometric mean and standard deviation of annual real returns, 1900-2022
export const STOCK_REAL_MEAN = 0.057;    // 5.7% real
export const STOCK_REAL_STD = 0.17;      // 17% std dev
export const BOND_REAL_MEAN = 0.021;     // 2.1% real
export const BOND_REAL_STD = 0.10;       // 10% std dev
export const INFLATION_MEAN = 0.02;      // 2% target, Bank of Canada

// Salary growth: real wage growth ~1% per year on average
// Source: Statistics Canada, Table 14-10-0063-01
export const REAL_WAGE_GROWTH = 0.01;

// --- Government benefits ---

// CPP (Canada Pension Plan) 2024
// Source: https://www.canada.ca/en/services/benefits/publicpensions/cpp.html
// Max monthly at 65: $1,364.60. Average: ~$815.
// Simplified: you get (years_contributed / 39) * max, capped at max.
export const CPP_MAX_MONTHLY = 1364.60;
export const CPP_CONTRIB_YEARS_FULL = 39;

// OAS (Old Age Security) 2024
// Source: https://www.canada.ca/en/services/benefits/publicpensions/cpp/old-age-security.html
// Max monthly at 65: $727.67. Full OAS after 40 years in Canada (we assume full).
export const OAS_MAX_MONTHLY = 727.67;

// --- Contribution limits ---

// TFSA annual limit 2024: $7,000
// Source: https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/tax-free-savings-account.html
export const TFSA_ANNUAL_LIMIT = 7000;

// RRSP: 18% of previous year's earned income, max $31,560 for 2024
// Source: https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/rrsps-related-plans.html
export const RRSP_RATE = 0.18;
export const RRSP_ANNUAL_MAX = 31560;

// Investment mix default: 60% stocks, 40% bonds
export const DEFAULT_STOCK_FRAC = 0.60;

import {
  QX_MALE, QX_FEMALE,
  SMOKING_RR, exerciseRR, sleepRR, alcoholRR, healthyFraction,
  STOCK_REAL_MEAN, STOCK_REAL_STD, BOND_REAL_MEAN, BOND_REAL_STD,
  INFLATION_MEAN, REAL_WAGE_GROWTH,
  CPP_MAX_MONTHLY, CPP_CONTRIB_YEARS_FULL, OAS_MAX_MONTHLY,
  TFSA_ANNUAL_LIMIT, RRSP_RATE, RRSP_ANNUAL_MAX,
  DEFAULT_STOCK_FRAC,
} from "./data.js";

const DEFAULTS = {
  name: "Person", age: 20, sex: "male", province: "ON",
  income_per_year: 55000,
  savings: { tfsa: 0, rrsp: 0, other: 0 },
  saving_per_month: 0, retirement_age: 65,
  habits: { exercise_per_week: 2, sleep_hours: 7, smoker: false, drinks_per_week: 3 },
};

function merge(defaults, input) {
  const out = { ...defaults };
  for (const k of Object.keys(input)) {
    if (input[k] != null && typeof input[k] === "object" && !Array.isArray(input[k])) {
      out[k] = { ...defaults[k], ...input[k] };
    } else if (input[k] != null) {
      out[k] = input[k];
    }
  }
  return out;
}

// Simple Box-Muller for normal random numbers
function randn() {
  let u, v;
  do { u = Math.random(); } while (u === 0);
  v = Math.random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

function drawReturn(mean, std) {
  return mean + std * randn();
}

function percentile(arr, p) {
  const sorted = arr.slice().sort((a, b) => a - b);
  const i = p * (sorted.length - 1);
  const lo = Math.floor(i);
  const hi = Math.ceil(i);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (i - lo);
}

function simulateOneLife(input) {
  const stockFrac = DEFAULT_STOCK_FRAC;
  const bondFrac = 1 - stockFrac;

  const qxBase = input.sex === "female" ? QX_FEMALE : QX_MALE;
  const habitRR =
    (input.habits.smoker ? SMOKING_RR : 1.0) *
    exerciseRR(input.habits.exercise_per_week) *
    sleepRR(input.habits.sleep_hours) *
    alcoholRR(input.habits.drinks_per_week);

  let savings = input.savings.tfsa + input.savings.rrsp + input.savings.other;
  let income = input.income_per_year;
  const annualSaving = input.saving_per_month * 12;
  const retireAge = input.retirement_age;
  let alive = true;
  let deathAge = 100;
  const hFrac = healthyFraction(input.habits);

  const yearsWorked = Math.max(0, input.age - 18);

  for (let age = input.age; age <= 100 && alive; age++) {
    // Mortality check
    const qx = Math.min(qxBase[Math.min(age, 100)] * habitRR, 0.99);
    if (Math.random() < qx) {
      deathAge = age;
      alive = false;
      break;
    }

    // Financial
    const stockReturn = drawReturn(STOCK_REAL_MEAN, STOCK_REAL_STD);
    const bondReturn = drawReturn(BOND_REAL_MEAN, BOND_REAL_STD);
    const portfolioReturn = stockFrac * stockReturn + bondFrac * bondReturn;

    if (age < retireAge) {
      // Working years
      const maxRRSP = Math.min(income * RRSP_RATE, RRSP_ANNUAL_MAX);
      const maxContrib = TFSA_ANNUAL_LIMIT + maxRRSP;
      const contrib = Math.min(annualSaving, maxContrib);
      savings = savings * (1 + portfolioReturn) + contrib;
      income *= (1 + REAL_WAGE_GROWTH);
    } else {
      // Retired
      const totalWorked = yearsWorked + (retireAge - input.age);
      const cppFrac = Math.min(totalWorked / CPP_CONTRIB_YEARS_FULL, 1);
      const govIncome = (CPP_MAX_MONTHLY * cppFrac + OAS_MAX_MONTHLY) * 12;
      const targetSpend = income * 0.70;
      const withdrawal = Math.max(0, targetSpend - govIncome);
      savings = savings * (1 + portfolioReturn) - withdrawal;
      if (savings < 0) savings = 0;
    }
  }

  const savingsAt70 = alive || deathAge >= 70 ? savings : 0;
  const totalWorked = yearsWorked + (Math.min(retireAge, deathAge) - input.age);
  const cppFrac = Math.min(Math.max(totalWorked, 0) / CPP_CONTRIB_YEARS_FULL, 1);
  const retiredIncome = (CPP_MAX_MONTHLY * cppFrac + OAS_MAX_MONTHLY) * 12;

  return {
    deathAge,
    savingsAt70,
    retiredIncome,
    healthyYears: Math.round(deathAge * hFrac),
    moneyLastsTo90: savings > 0 && deathAge >= 90 ? 1 : 0,
  };
}

export function simulate(inputFields, { numLives = 5000 } = {}) {
  const input = merge(DEFAULTS, inputFields || {});
  const deaths = [];
  const savings70 = [];
  const incomes = [];
  const healthy = [];
  let lastsTo90 = 0;

  for (let i = 0; i < numLives; i++) {
    const life = simulateOneLife(input);
    deaths.push(life.deathAge);
    savings70.push(life.savingsAt70);
    incomes.push(life.retiredIncome);
    healthy.push(life.healthyYears);
    lastsTo90 += life.moneyLastsTo90;
  }

  const facts = {
    savings_70: {
      low: Math.round(percentile(savings70, 0.1)),
      median: Math.round(percentile(savings70, 0.5)),
      high: Math.round(percentile(savings70, 0.9)),
    },
    income_retired_per_year: {
      low: Math.round(percentile(incomes, 0.1)),
      median: Math.round(percentile(incomes, 0.5)),
      high: Math.round(percentile(incomes, 0.9)),
    },
    money_lasts_to_90_chance: Math.round((lastsTo90 / numLives) * 100) / 100,
    life_expectancy: {
      low: Math.round(percentile(deaths, 0.1)),
      median: Math.round(percentile(deaths, 0.5)),
      high: Math.round(percentile(deaths, 0.9)),
    },
    healthy_years: {
      low: Math.round(percentile(healthy, 0.1)),
      median: Math.round(percentile(healthy, 0.5)),
      high: Math.round(percentile(healthy, 0.9)),
    },
    apparent_age_at_70: 70,
    one_change: null,
    sources: [
      { value: "life_tables", url: "https://www150.statcan.gc.ca/t1/tbl1/en/tv.action?pid=1310011401", fetched_at: "2026-11-21T00:00:00Z" },
      { value: "cpp_max", url: "https://www.canada.ca/en/services/benefits/publicpensions/cpp.html", fetched_at: "2026-11-21T00:00:00Z" },
      { value: "oas_max", url: "https://www.canada.ca/en/services/benefits/publicpensions/cpp/old-age-security.html", fetched_at: "2026-11-21T00:00:00Z" },
      { value: "tfsa_limit", url: "https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/tax-free-savings-account.html", fetched_at: "2026-11-21T00:00:00Z" },
      { value: "returns", url: "https://www.credit-suisse.com/about-us/en/reports-research/global-investment-returns-yearbook.html", fetched_at: "2026-11-21T00:00:00Z" },
    ],
  };

  // Rank the one change that matters most
  facts.one_change = rankBestChange(input, facts, numLives);

  // Apparent age: shift by health path
  const baseLE = input.sex === "female" ? 84 : 80;
  const leDiff = facts.life_expectancy.median - baseLE;
  facts.apparent_age_at_70 = Math.round(70 - leDiff * 0.3);

  return facts;
}

const SLIDER_NUDGES = [
  { slider: "saving_per_month", nudge: (input) => ({ ...input, saving_per_month: input.saving_per_month + 50 }), label: (input) => `saving $${input.saving_per_month + 50 - input.saving_per_month} more a month` },
  { slider: "exercise_per_week", nudge: (input) => ({ ...input, habits: { ...input.habits, exercise_per_week: Math.min(input.habits.exercise_per_week + 2, 7) } }), label: () => "exercising twice more a week" },
  { slider: "sleep_hours", nudge: (input) => ({ ...input, habits: { ...input.habits, sleep_hours: 7.5 } }), label: () => "getting seven to eight hours of sleep" },
  { slider: "smoker", nudge: (input) => ({ ...input, habits: { ...input.habits, smoker: false } }), label: () => "quitting smoking" },
];

function rankBestChange(input, baseFacts, numLives) {
  let best = null;
  let bestScore = 0;

  for (const { slider, nudge, label } of SLIDER_NUDGES) {
    const nudged = nudge(input);
    // Skip if no change
    if (JSON.stringify(nudged) === JSON.stringify(input)) continue;

    const nudgedFacts = simulate(nudged, { numLives: Math.min(numLives, 1000) });
    const savingsGain = nudgedFacts.savings_70.median - baseFacts.savings_70.median;
    const yearsGain = nudgedFacts.life_expectancy.median - baseFacts.life_expectancy.median;
    const score = savingsGain / 50000 + yearsGain;

    if (score > bestScore) {
      bestScore = score;
      best = { slider, label: label(input) };
    }
  }

  return best || { slider: "saving_per_month", label: "saving $50 more a month" };
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { simulate } from "./engine.js";

const SAMPLE_INPUT = {
  name: "Ethan", age: 21, sex: "male", province: "ON",
  income_per_year: 55000,
  savings: { tfsa: 2000, rrsp: 0, other: 500 },
  saving_per_month: 200, retirement_age: 65,
  habits: { exercise_per_week: 3, sleep_hours: 7, smoker: false, drinks_per_week: 2 },
};

describe("simulate", () => {
  it("returns a facts sheet matching the contract schema", () => {
    const facts = simulate(SAMPLE_INPUT, { numLives: 500 });
    assert.ok(facts.savings_70.low <= facts.savings_70.median);
    assert.ok(facts.savings_70.median <= facts.savings_70.high);
    assert.ok(facts.income_retired_per_year.low > 0);
    assert.ok(facts.money_lasts_to_90_chance >= 0 && facts.money_lasts_to_90_chance <= 1);
    assert.ok(facts.life_expectancy.low > 0);
    assert.ok(facts.life_expectancy.median > facts.life_expectancy.low);
    assert.ok(facts.healthy_years.median > 0);
    assert.ok(facts.apparent_age_at_70 > 60 && facts.apparent_age_at_70 < 80);
    assert.ok(facts.one_change);
    assert.ok(facts.one_change.slider);
    assert.ok(facts.one_change.label);
    assert.ok(Array.isArray(facts.sources));
  });

  it("produces reasonable life expectancy for a healthy male", () => {
    const facts = simulate(SAMPLE_INPUT, { numLives: 2000 });
    // StatsCan 2020-2022: male life expectancy ~80
    assert.ok(facts.life_expectancy.median >= 70, `median LE ${facts.life_expectancy.median} too low`);
    assert.ok(facts.life_expectancy.median <= 92, `median LE ${facts.life_expectancy.median} too high`);
  });

  it("produces reasonable life expectancy for a healthy female", () => {
    const facts = simulate({ ...SAMPLE_INPUT, sex: "female" }, { numLives: 2000 });
    // StatsCan 2020-2022: female life expectancy ~84
    assert.ok(facts.life_expectancy.median >= 74, `median LE ${facts.life_expectancy.median} too low`);
    assert.ok(facts.life_expectancy.median <= 96, `median LE ${facts.life_expectancy.median} too high`);
  });

  it("smoking reduces life expectancy", () => {
    const healthy = simulate(SAMPLE_INPUT, { numLives: 2000 });
    const smoker = simulate({
      ...SAMPLE_INPUT,
      habits: { ...SAMPLE_INPUT.habits, smoker: true },
    }, { numLives: 2000 });
    assert.ok(
      smoker.life_expectancy.median < healthy.life_expectancy.median,
      `smoker LE ${smoker.life_expectancy.median} should be less than healthy ${healthy.life_expectancy.median}`
    );
  });

  it("more saving increases savings at 70", () => {
    const low = simulate({ ...SAMPLE_INPUT, saving_per_month: 50 }, { numLives: 2000 });
    const high = simulate({ ...SAMPLE_INPUT, saving_per_month: 500 }, { numLives: 2000 });
    assert.ok(
      high.savings_70.median > low.savings_70.median,
      `$500/mo savings ${high.savings_70.median} should exceed $50/mo ${low.savings_70.median}`
    );
  });

  it("runs 5000 lives in under 100ms", () => {
    const start = performance.now();
    simulate(SAMPLE_INPUT, { numLives: 5000 });
    const elapsed = performance.now() - start;
    assert.ok(elapsed < 100, `took ${elapsed.toFixed(1)}ms, limit is 100ms`);
  });

  it("works with default inputs (no fields provided)", () => {
    const facts = simulate({}, { numLives: 500 });
    assert.ok(facts.savings_70.median >= 0);
    assert.ok(facts.life_expectancy.median > 50);
  });

  it("includes government income in retired income", () => {
    const facts = simulate(SAMPLE_INPUT, { numLives: 500 });
    // CPP + OAS minimum is roughly $10k+/year
    assert.ok(
      facts.income_retired_per_year.low >= 8000,
      `retired income low ${facts.income_retired_per_year.low} should include CPP+OAS`
    );
  });
});

