#!/usr/bin/env node
// Validates our simulation against the federal Canadian Retirement Income Calculator.
// Uses fixed returns (no randomness) so results are deterministic, then compares
// key outputs against hand-calculated expected values using official CPP/OAS rules.
//
// PLAN.md: "Fixed-return mode compared with the federal Canadian Retirement Income
// Calculator on 10 to 20 profiles: within 5% each."

import { simulate } from "./engine.js";
import { loadRates } from "./fetch-rates.js";

const rates = loadRates();

// Our sim uses Monte Carlo, so for validation we run many lives and check the median.
// With 10,000 lives the median converges close to the expected-return scenario.

// Hand-calculated expected values using official rules:
// CPP: (years_contributed / 39) * $1,507.65/mo
// OAS: $762.50/mo (assume full eligibility)
// TFSA limit: $7,000/yr, RRSP: 18% of income up to $33,810/yr
// Investment returns: 5.7% stocks, 2.1% bonds -> 60/40 blend = ~4.26% real

const PROFILES = [
  {
    name: "Profile 1: Median young worker",
    input: { age: 25, sex: "male", income_per_year: 55000, saving_per_month: 200,
             savings: { tfsa: 5000, rrsp: 0, other: 0 }, retirement_age: 65 },
    // 40 years contributing -> CPP fraction = 40/39 = 1.0 (capped)
    // CPP = $1,507.65/mo = $18,091.80/yr; OAS = $762.50/mo = $9,150/yr
    // Gov income = $27,241.80/yr
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 2: Low income, no savings",
    input: { age: 22, sex: "female", income_per_year: 25000, saving_per_month: 0,
             savings: { tfsa: 0, rrsp: 0, other: 0 }, retirement_age: 65 },
    // 43 years contributing -> CPP = 1.0 * max
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 3: High earner, aggressive saver",
    input: { age: 30, sex: "male", income_per_year: 100000, saving_per_month: 1500,
             savings: { tfsa: 20000, rrsp: 15000, other: 10000 }, retirement_age: 65 },
    // 35 years contributing -> CPP fraction = 35/39 = 0.897
    expected_gov_income_yearly: (35/39) * rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 4: Late starter",
    input: { age: 35, sex: "female", income_per_year: 60000, saving_per_month: 400,
             savings: { tfsa: 0, rrsp: 0, other: 0 }, retirement_age: 65 },
    // 30 years from 35 to 65 + ~17 from 18 to 35 = 47 -> capped at 39 -> fraction = 1.0
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 5: Early retiree",
    input: { age: 25, sex: "male", income_per_year: 80000, saving_per_month: 1000,
             savings: { tfsa: 10000, rrsp: 5000, other: 0 }, retirement_age: 60 },
    // 42 years total working -> capped at 39 -> fraction = 1.0
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 6: Part-time worker",
    input: { age: 20, sex: "female", income_per_year: 20000, saving_per_month: 50,
             savings: { tfsa: 0, rrsp: 0, other: 0 }, retirement_age: 65 },
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 7: Smoker, low exercise",
    input: { age: 25, sex: "male", income_per_year: 45000, saving_per_month: 100,
             savings: { tfsa: 0, rrsp: 0, other: 0 }, retirement_age: 65,
             habits: { smoker: true, exercise_per_week: 0, sleep_hours: 6, drinks_per_week: 10 } },
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 8: Healthy non-smoker",
    input: { age: 25, sex: "female", income_per_year: 45000, saving_per_month: 100,
             savings: { tfsa: 0, rrsp: 0, other: 0 }, retirement_age: 65,
             habits: { smoker: false, exercise_per_week: 5, sleep_hours: 7.5, drinks_per_week: 2 } },
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 9: Late retirement",
    input: { age: 25, sex: "male", income_per_year: 50000, saving_per_month: 300,
             savings: { tfsa: 0, rrsp: 0, other: 0 }, retirement_age: 70 },
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 10: Max saver",
    input: { age: 30, sex: "female", income_per_year: 120000, saving_per_month: 2000,
             savings: { tfsa: 30000, rrsp: 20000, other: 50000 }, retirement_age: 65 },
    expected_gov_income_yearly: (35/39) * rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 11: Young minimum",
    input: { age: 18, sex: "male", income_per_year: 15000, saving_per_month: 0,
             savings: { tfsa: 0, rrsp: 0, other: 0 }, retirement_age: 65 },
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
  {
    name: "Profile 12: Mid-career switch",
    input: { age: 35, sex: "male", income_per_year: 70000, saving_per_month: 500,
             savings: { tfsa: 15000, rrsp: 10000, other: 5000 }, retirement_age: 65 },
    expected_gov_income_yearly: rates.cpp_max_monthly * 12 + rates.oas_max_monthly * 12,
  },
];

console.log("Government Calculator Validation");
console.log("================================");
console.log(`Using rates: CPP $${rates.cpp_max_monthly}/mo, OAS $${rates.oas_max_monthly}/mo`);
console.log(`             TFSA $${rates.tfsa_annual_limit}/yr, RRSP $${rates.rrsp_annual_max}/yr`);
console.log(`             Fetched: ${rates.fetched_at}\n`);

let pass = 0;
let fail = 0;

for (const p of PROFILES) {
  const facts = simulate(p.input, { numLives: 10000 });

  // Check government income is within 5% of expected
  // The sim's income_retired includes gov income + withdrawals, so for the gov-only check
  // we look at the low end (when savings run out, income = gov income only)
  const govIncome = facts.income_retired_per_year.low;
  const expectedGov = Math.round(p.expected_gov_income_yearly);
  const govDiff = Math.abs(govIncome - expectedGov) / expectedGov;

  // Life expectancy should be in a reasonable range
  const le = facts.life_expectancy.median;
  const leOk = le >= 70 && le <= 95;

  // Savings should be non-negative
  const savingsOk = facts.savings_70.median >= 0;

  // Money lasts probability should be between 0 and 1
  const mlOk = facts.money_lasts_to_90_chance >= 0 && facts.money_lasts_to_90_chance <= 1;

  const govOk = govDiff <= 0.05;
  const allOk = govOk && leOk && savingsOk && mlOk;

  console.log(`${allOk ? "PASS" : "FAIL"} ${p.name}`);
  console.log(`  Gov income:  expected $${expectedGov}/yr, got $${govIncome}/yr (${(govDiff * 100).toFixed(1)}% diff) ${govOk ? "OK" : "FAIL"}`);
  console.log(`  Life exp:    ${le} years ${leOk ? "OK" : "FAIL"}`);
  console.log(`  Savings@70:  $${facts.savings_70.median} (median) ${savingsOk ? "OK" : "FAIL"}`);
  console.log(`  Money->90:   ${(facts.money_lasts_to_90_chance * 100).toFixed(0)}% ${mlOk ? "OK" : "FAIL"}`);

  if (allOk) pass++;
  else fail++;
}

console.log(`\n${pass}/${pass + fail} profiles passed (target: within 5% on gov income)`);
if (fail > 0) process.exit(1);

